head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[searchbox > M > getValue]<br/>SearchBox 컴포넌트의 실제 입력값을 반환합니다.",
    "validation" : [
        "포맷이 제거된 실제 입력값을 반환합니다.",
        "값이 비어 있으면 빈 문자열('') 을 반환합니다.",        
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.getValue = function(target) {
    let rtn = '';
    rtn = target.getValue();

    wf_body_bottom.getObj("scwin").setReturnValue("getValue : " + rtn);
}



// 사용자 정의 함수
scwin.fn_dpformatter = function(val) {
    return "language -> " + val;
};



// target1
scwin.btn_setValue1_onclick = function (e) {
    target1.setValue("langkoKR");
};

scwin.btn_getValue1_onclick = function (e) {
    scwin.getValue(target1);
}

// target2
scwin.btn_setValue2_onclick = function (e) {
    target2.setValue("-1234.5678");
};

scwin.btn_getValue2_onclick = function (e) {
    scwin.getValue(target2);
}

// target3
scwin.btn_setValue3_onclick = function (e) {
    target3.setValue("20080501");
};

scwin.btn_getValue3_onclick = function (e) {
    scwin.getValue(target3);
};

// target4
scwin.btn_setValue4_onclick = function (e) {
    target4.setValue("121521");
};

scwin.btn_getValue4_onclick = function (e) {
    scwin.getValue(target4);
};

// target5
scwin.btn_setValue5_onclick = function (e) {
    target5.setValue("1234.5");
};

scwin.btn_getValue5_onclick = function (e) {
    scwin.getValue(target5);
};

// target6
scwin.btn_setValue6_onclick = function (e) {
    target6.setValue("1234.5612");
};

scwin.btn_getValue6_onclick = function (e) {
    scwin.getValue(target6);
};

// target7 : 빈 값 - 빈 문자열 반환 검증
scwin.btn_setValue7_onclick = function (e) {
    target7.setValue("");
};

scwin.btn_getValue7_onclick = function (e) {
    scwin.getValue(target7);
};

// target8 : displayFormatter 적용 후에도 실제 입력값 반환 검증
scwin.btn_setValue8_onclick = function (e) {
    target8.setValue("langkoKR");
}

scwin.btn_getValue8_onclick = function (e) {
    scwin.getValue(target8);
}

// getFormattedValue 비교용 - 표시값 확인 (target1)
scwin.btn_getFormattedValue1_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("getFormattedValue : " + target1.getFormattedValue());
}


scwin.btn_setAll_onclick = function (e) {
    for (var i = 1; i < 9; i ++)
        eval("scwin.btn_setValue"+i+"_onclick()");
}

scwin.btn_getAll_onclick = function (e) {
    for (var i = 1; i < 9; i ++)
        eval("scwin.btn_getValue"+i+"_onclick()");
};
